// BE_PDFGetPages writes a page range of a PDF to a new file. The PDFs are generated by the writer; no sample file is used.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pdf, appendPdf } from '../../scripts/src/pdf.ts';
import { evaluateText } from '../../calc/src/index.ts';
import { pdfPageCount, pdfText } from '../../calc/src/pdf-text.ts';

const page = (n: number) => ({ width: 200, height: 200, ops: [{ kind: 'text' as const, text: `Page number ${n}`, left: 10, top: 10, width: 180, height: 20 }] });
const five = Buffer.from(pdf([1, 2, 3, 4, 5].map(page)));

function run(expr: string, source: Uint8Array = five) {
  const written = new Map<string, Uint8Array>();
  const files = {
    read: (p: string) => (p === '/docs/in.pdf' ? source : undefined),
    write: (p: string, content: string | Uint8Array) => (p.startsWith('/docs/') ? (written.set(p, Buffer.from(content)), true) : false),
    size: () => undefined,
  };
  const result = evaluateText(`${expr} & "/" & BE_GetLastError`, {
    field: (r: { field: string }) => (r.field === 'f' ? ({ type: 'container', value: 'a.pdf', data: source } as never) : undefined), files,
  } as never);
  return { result, written };
}

test('BE_PDFGetPages writes the pages asked for, from a path or a container', () => {
  const r = run('BE_PDFGetPages ( "/docs/in.pdf" ; "/docs/out.pdf" ; 2 ; 4 )');
  assert.equal(r.result, '/0');
  const out = r.written.get('/docs/out.pdf')!;
  assert.equal(pdfPageCount(out), 3);
  assert.equal(pdfText(out), 'Page number 2\rPage number 3\rPage number 4');
  const c = run('BE_PDFGetPages ( f ; "/docs/c.pdf" ; 5 )');
  assert.equal(c.result, '/0');
  assert.equal(pdfText(c.written.get('/docs/c.pdf')!), 'Page number 5');
  // The pages of a file with pages added later come out too.
  const longer = Buffer.concat([five, appendPdf(five, [page(6)])]);
  assert.equal(pdfText(run('BE_PDFGetPages ( "/docs/in.pdf" ; "/docs/o.pdf" ; 6 )', longer).written.get('/docs/o.pdf')!), 'Page number 6');
  // A page past the end is cut off at the last page.
  assert.equal(pdfPageCount(run('BE_PDFGetPages ( "/docs/in.pdf" ; "/docs/o.pdf" ; 4 ; 99 )').written.get('/docs/o.pdf')!), 2);
});

test('BE_PDFGetPages refuses what it cannot cut', () => {
  for (const args of ['0 ; 1', '6 ; 7', '3 ; 2']) {
    const r = run(`BE_PDFGetPages ( "/docs/in.pdf" ; "/docs/out.pdf" ; ${args} )`);
    assert.equal(r.result, '?/-1', args);
    assert.equal(r.written.size, 0);
  }
  assert.equal(run('BE_PDFGetPages ( "/docs/in.pdf" ; "/docs/out.pdf" ; 1 )', Buffer.from('not a pdf')).result, '?/-1');
  assert.equal(run('BE_PDFGetPages ( "/docs/missing.pdf" ; "/docs/out.pdf" ; 1 )').result, '?/2');
  assert.equal(run('BE_PDFGetPages ( "/docs/in.pdf" ; "/elsewhere/out.pdf" ; 1 )').result, '?/2');
});
